script.setup:
// tween.js drives every dot: each move is one Tween per dot (position, turn, size, color)
// with a staggered delay and the chosen easing. The inset plots that easing curve.
const mod = await ctx.utils.import("https://esm.sh/@tweenjs/tween.js@25.0.0");
const { Tween, Group, Easing } = mod.Tween ? mod : (mod.default ?? mod);
const COLS = 12, ROWS = 8, M = COLS * ROWS;
const dots = Array.from({ length: M }, (_, i) => ({ x: 0, y: 0, rot: 0, size: 0, hue: 0, i }));
const EASINGS = [
  ["Elastic.Out", Easing.Elastic.Out], ["Back.InOut", Easing.Back.InOut], ["Bounce.Out", Easing.Bounce.Out],
  ["Exponential.InOut", Easing.Exponential.InOut], ["Cubic.InOut", Easing.Cubic.InOut], ["Circular.InOut", Easing.Circular.InOut],
  ["Sinusoidal.InOut", Easing.Sinusoidal.InOut], ["Quintic.Out", Easing.Quintic.Out], ["Linear", Easing.Linear.None],
];
// Formations, in a 1000-unit-tall frame centered on the origin.
const FORMATIONS = [
  (i) => ({ x: ((i % COLS) - (COLS - 1) / 2) * 62, y: (Math.floor(i / COLS) - (ROWS - 1) / 2) * 62, rot: 0, size: 1, hue: ((i % COLS) + Math.floor(i / COLS)) / (COLS + ROWS - 2) }),
  (i) => { const a = i / M * Math.PI * 2; return { x: Math.cos(a) * 380, y: Math.sin(a) * 380, rot: a, size: 0.5, hue: i / M }; },
  (i) => { const a = i * 2.39996, r = 34 * Math.sqrt(i + 1); return { x: Math.cos(a) * r, y: Math.sin(a) * r, rot: a, size: 0.45 + i / M * 0.75, hue: 1 - i / M }; },
  (i) => { const t = i / (M - 1); return { x: (t - 0.5) * 1150, y: Math.sin(t * Math.PI * 4) * 190 + (i % 2 ? 40 : -40), rot: t * Math.PI * 4, size: 0.7, hue: t }; },
  (i) => { const ring = i % 3, k = Math.floor(i / 3), n = M / 3, a = k / n * Math.PI * 2 + ring * 0.2; const r = 120 + ring * 120; return { x: Math.cos(a) * r, y: Math.sin(a) * r, rot: -a, size: 0.45 + ring * 0.25, hue: 0.15 + ring * 0.35 }; },
];
const gl = ctx.gl;
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 20, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 20, 8);
gl.bindVertexArray(null);
const lineVao = gl.createVertexArray(), lineBuffer = gl.createBuffer();
gl.bindVertexArray(lineVao); gl.bindBuffer(gl.ARRAY_BUFFER, lineBuffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindVertexArray(null);
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec3 a_info;
uniform vec2 u_view; uniform float u_px; out float v_rot; out float v_hue;
void main(){
  v_rot = a_info.x; v_hue = a_info.z;
  gl_Position = vec4(a_position / u_view * 2.0, 0.0, 1.0);
  gl_PointSize = max(a_info.y, 0.0) * u_px;
}`, `#version 300 es
precision highp float; in float v_rot; in float v_hue; out vec4 outColor;
uniform vec3 u_colors[5];
void main(){
  // A rounded square, turned by the tweened angle.
  vec2 p = gl_PointCoord * 2.0 - 1.0;
  float c = cos(v_rot), s = sin(v_rot);
  p = mat2(c, -s, s, c) * p * 1.42;
  vec2 q = abs(p) - vec2(0.62);
  float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - 0.3;
  if (d > 0.0) discard;
  float h = clamp(v_hue, 0.0, 1.0) * 4.0; int k = int(min(floor(h), 3.0));
  vec3 col = mix(u_colors[k], u_colors[k + 1], h - float(k));
  outColor = vec4(col * (0.8 + 0.35 * smoothstep(-0.25, 0.0, -d) * (0.5 + 0.5 * p.y)), 1.0);
}`);
const lines = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; uniform vec2 u_offset;
void main(){ gl_Position = vec4(a_position + u_offset, 0.0, 1.0); gl_PointSize = 9.0; }`, `#version 300 es
precision highp float; out vec4 outColor; uniform vec3 u_color;
void main(){ outColor = vec4(u_color, 1.0); }`);
Object.assign(ctx.state, { Tween, Group, group: new Group(), EASINGS, FORMATIONS, dots, M, vao, buffer, lineVao, lineBuffer, program, lines,
  data: new Float32Array(M * 5), formation: -1, nextAt: 0, moveStart: 0, moveLength: 1, easing: 0, moves: 0 });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const now = ctx.time * 1000 + 1; // tween.js reads 0 as "use the clock", so never pass 0
// Time for the next move: one Tween per dot, staggered by index or by distance from the middle.
if (now >= s.nextAt) {
  s.formation = (s.formation + 1) % s.FORMATIONS.length;
  s.easing = u.u_easing > 0 ? u.u_easing - 1 : s.moves % s.EASINGS.length;
  s.moves++;
  const ease = s.EASINGS[s.easing][1], dur = u.u_duration * 1000, step = u.u_stagger * 1000;
  const fromCenter = s.formation % 2 === 1;
  s.group.removeAll();
  let longest = 0;
  for (const d of s.dots) {
    const target = s.FORMATIONS[s.formation](d.i);
    if (s.formation === 0) target.rot = d.rot - (d.rot % (Math.PI / 2)) + Math.PI / 2; // grid: a quarter turn
    const delay = fromCenter ? Math.hypot(d.x, d.y) / 25 * step : d.i * step;
    longest = Math.max(longest, delay);
    new s.Tween(d, s.group).to(target, dur).easing(ease).delay(delay).start(now);
  }
  s.moveStart = now; s.moveLength = longest + dur;
  s.nextAt = now + s.moveLength + u.u_pause * 1000;
}
s.group.update(now);
s.dots.forEach((d, i) => s.data.set([d.x, d.y, d.rot, d.size * 46 * u.u_scale, d.hue], i * 5));
const H = 1000, W = H * w / h;
gl.clearColor(0.035, 0.035, 0.05, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_view: [W, H], u_px: h / H, u_colors: [u.u_c1, u.u_c2, u.u_c3, u.u_c4, u.u_c1].flat() });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.data, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.M);
// Inset: the current easing curve, with a dot riding it for the first dot's tween.
const [name, ease] = s.EASINGS[s.easing];
const bw = 0.22 * h / w * 2, bh = 0.22 * 2, x0 = -1 + 0.05 * h / w * 2, y0 = -1 + 0.08;
const sx = (t) => x0 + t * bw, sy = (v) => y0 + 0.2 * bh + v * bh * 0.6;
const curve = [];
for (let k = 0; k <= 120; k++) { const t = k / 120; curve.push(sx(t), sy(ease(t))); }
const frame = [sx(0), sy(0), sx(1), sy(0), sx(0), sy(0), sx(0), sy(1), sx(0), sy(1), sx(1), sy(1)];
const tFirst = Math.min(1, Math.max(0, (now - s.moveStart) / (u.u_duration * 1000)));
gl.useProgram(s.lines);
gl.bindVertexArray(s.lineVao); gl.bindBuffer(gl.ARRAY_BUFFER, s.lineBuffer);
const draw = (pts, mode, color) => {
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(pts), gl.DYNAMIC_DRAW);
  ctx.utils.setUniforms(s.lines, { u_color: color });
  // WebGL lines are 1 px; shifted passes thicken them.
  for (const o of [[0, 0], [2 / w, 0], [0, 2 / h], [2 / w, 2 / h]]) { ctx.utils.setUniforms(s.lines, { u_offset: o }); gl.drawArrays(mode, 0, pts.length / 2); }
};
draw(frame, gl.LINES, [0.2, 0.21, 0.27]);
draw(curve, gl.LINE_STRIP, u.u_c2);
draw([sx(tFirst), sy(ease(tFirst))], gl.POINTS, [1, 1, 1]);
gl.bindVertexArray(null);
ctx.publish("easing", name);
